import { sharedBillPage } from './bill-ui.js';
const $ = s => document.querySelector(s);
const app = $('#app'), dialog = $('#dialog');
let billDirty = false;
let state, page = 'overview', busy = false, billPreview = null, walletDetail = null, requestFilter = 'received', walletFilter = 'active', activityFilter = '', billFilter = 'active', activityWallet = 'personal', expenseFilter = 'open';
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd = x => new Intl.NumberFormat('en-US', {style:'currency', currency:'USD'}).format(Number(x || 0));
const date = x => new Date(x).toLocaleDateString('en-GB', {day:'numeric', month:'short'});
const same = (a,b) => String(a) === String(b);
const personal = () => state.wallets.find(w => w.wallet_type === 'personal');
const sharedWallets = () => state.wallets.filter(w => w.wallet_type === 'shared' && w.purpose !== 'bill');
const activeShared = () => sharedWallets().filter(w => w.status === 'active');
const paths = {
 home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
 wallet:'M20 8V5a2 2 0 0 0-2-2H6a3 3 0 0 0 0 6h15v11H6a3 3 0 0 1-3-3V6m18 7h-5v4h5',
 send:'m7 17 10-10M7 7h10v10', receive:'M17 7 7 17m10 0H7V7', plus:'M12 5v14M5 12h14',
 receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Zm4 4h6m-6 4h6m-6 4h3',
 activity:'M3 12h4l3-8 4 16 3-8h4', business:'M4 21V7h16v14M9 7V3h6v4M2 21h20M8 11h1m6 0h1m-8 4h1m6 0h1m-6 6v-3h2v3',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13m0-13H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z',
 compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-5-4-3 5-5 3 3-5 5-3Z',
 arrow:'M5 12h14m-5-5 5 5-5 5', back:'M19 12H5m5 5-5-5 5-5', check:'m5 12 4 4L19 6',
 close:'m6 6 12 12M6 18 18 6', bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0',
 more:'M5 12h.01M12 12h.01M19 12h.01', search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',
 lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4', logout:'M9 21H4V3h5m5 5 4 4-4 4m-6-4h10',
 archive:'M3 3h18v5H3zM5 8v13h14V8m-10 5h6', tag:'M3 3h8l10 10-8 8L3 11V3Zm4 4h.01',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z', bag:'M4 7h16l1 14H3L4 7Zm4 0V5a4 4 0 0 1 8 0v2',
 utensils:'M4 3v6a3 3 0 0 0 6 0V3M7 3v18M20 21V3c-5 3-5 10 0 10', settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2'
};
const icon = (name, cls = '') => `<svg class="icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.grid}"/></svg>`;
const brand = () => `<span class="brand-symbol" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none"><path d="M7 23V13a5 5 0 0 1 10 0v10m0-10a4 4 0 0 1 8 0v10" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"/></svg></span><span class="brand-name">lamma</span>`;
const labels = {overview:'Overview',wallets:'Shared wallets',requests:'Payment requests',bills:'Bills & splits',expenses:'Expenses',history:'Transactions',business:'Business',more:'More'};
const navIcons = {overview:'home',wallets:'wallet',requests:'receive',bills:'receipt',expenses:'tag',history:'activity',business:'business',more:'more'};
const badge = status => `<span class="badge ${esc(status)}">${esc(status.replaceAll('_',' '))}</span>`;
const button = (label, action, extra = '', cls = 'primary') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field = (label,name,type='text',value='',extra='') => `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0.01" inputmode="decimal" '+(extra.includes('step=')?'':'step="0.01"'):''} ${type==='tel'?'inputmode="tel" autocomplete="tel"':''} ${extra} required></label>`;
const select = (label,name,options,optional=false) => `<label>${label}<select name="${name}" aria-label="${esc(label)}" ${optional?'':'required'}>${options.map(([v,l])=>`<option value="${esc(v)}" ${name==='activity_wallet'&&same(v,activityWallet)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const amount = () => field('Amount (USD)','amount','number');
const walletOptions = (includePersonal=true) => state.wallets.filter(w=>w.status==='active'&&(includePersonal||w.wallet_type==='shared')&&!state.bills.some(b=>same(b.shared_wallet_id,w.wallet_id)&&b.split_method==='items')).map(w=>[w.wallet_id,w.name]);
const empty = (title,sub,symbol='check') => `<div class="empty"><span>${icon(symbol)}</span><h3>${title}</h3><p>${sub}</p></div>`;
const initials = u => esc((u.first_name?.[0] || '')+(u.last_name?.[0] || ''));
const customerBills = () => state.bills.filter(b=>state.wallets.some(w=>same(w.wallet_id,b.shared_wallet_id))||b.paid_by_me);
const pendingRequests = () => state.requests.filter(r=>same(r.payer_id,state.user.user_id)&&r.status==='pending'&&new Date(r.expires_at)>new Date());
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`show ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4000);}
const pendingButtons=new WeakMap();
function pendingButton(button,pending,label='Working…'){
 if(!button)return;
 if(pending){pendingButtons.set(button,button.innerHTML);button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML='<span class="spinner" aria-hidden="true"></span>'+label;}
 else{const original=pendingButtons.get(button);if(original!==undefined)button.innerHTML=original;button.disabled=false;button.removeAttribute('aria-busy');pendingButtons.delete(button);}
}
const lockedForms=new WeakMap();
function lockForm(form,locked){
 if(locked){const container=form.closest('dialog');const controls=[...form.elements,...(container?[container.querySelector('.modal-heading button')].filter(Boolean):[])];lockedForms.set(form,{controls:controls.map(control=>[control,control.disabled]),container});for(const control of controls)control.disabled=true;form.setAttribute('aria-busy','true');}
 else{const snapshot=lockedForms.get(form);if(snapshot)for(const [control,disabled] of snapshot.controls)control.disabled=disabled;form.removeAttribute('aria-busy');lockedForms.delete(form);}
}
function formError(form,error){
 const alert=form.isConnected?form.querySelector('[role=alert]'):null;
 if(alert){alert.textContent=error.message;alert.scrollIntoView({block:'nearest',behavior:'instant'});}else toast(error.message,true);
}
async function api(path,body,key){
 let res;try{res=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json',...(key?{'Idempotency-Key':key}:{})}:{},body:body?JSON.stringify(body):undefined});}catch{throw new Error('Could not connect. Check your connection and try again.');}
 let value;try{value=await res.json();}catch{throw new Error('The server returned an unexpected response. Please try again.');}
 if(!res.ok){const error=new Error(value.error||'This action could not be completed.');error.status=res.status;throw error;}return value;
}
function routeHash(){return page==='bill-detail'?'#bill/'+encodeURIComponent(billPreview.bill_code):page==='wallet-detail'?'#wallet/'+walletDetail.wallet.wallet_id:'#'+page;}
function readRoute(){
 const hash=location.hash.slice(1),bill=hash.match(/^bill\/([^/]+)$/),wallet=hash.match(/^wallet\/(\d+)$/);
 if(bill){try{page='bill-detail';billPreview={bill_code:decodeURIComponent(bill[1])};}catch{page='bills';billPreview=null;}}
 else if(wallet){page='wallet-detail';walletDetail={wallet:{wallet_id:wallet[1]}};}
 else page=Object.hasOwn(labels,hash)?hash:'overview';
}
let loadVersion=0;
async function load(){
 const version=++loadVersion,current=page;
 try{
  const next=await api('state');
  if(version!==loadVersion||page!==current)return false;state=next;
  const detail=page==='wallet-detail'&&walletDetail?await api('wallet?id='+walletDetail.wallet.wallet_id):page==='bill-detail'&&billPreview?await api('bill?code='+encodeURIComponent(billPreview.bill_code)):null;
  if(version!==loadVersion||page!==current)return false;
  state=next;if(page==='wallet-detail')walletDetail=detail;if(page==='bill-detail')billPreview=detail;render();return true;
 }catch(error){
  if(version!==loadVersion)return false;
  if(error.status===401)login();
  else if(state&&[400,403,404].includes(error.status)&&['wallet-detail','bill-detail'].includes(page)){page=page==='wallet-detail'?'wallets':'bills';billDirty=false;render();toast(error.message,true);}
  else{toast(error.message,true);if(!state)app.innerHTML=`<main class="connection-state"><span class="item-icon peach">${icon('activity')}</span><h1>Let’s reconnect</h1><p>${esc(error.message)}</p>${button('Try again','retry')}</main>`;}
  return false;
 }
}
function go(next){
 if(page==='bill-detail'&&billDirty&&next!==page&&!window.confirm('Leave without saving your item selections?'))return;
 if(page==='bill-detail'&&next!=='bill-detail')billDirty=false;
 page=next;loadVersion++;if(location.hash!==routeHash())history.pushState(null,'',routeHash());render();window.scrollTo({top:0,behavior:'instant'});app.querySelector('h1')?.focus({preventScroll:true});
}
function login(register=false){state=null;app.innerHTML=`<main class="auth"><section class="auth-story"><a class="wordmark" href="#overview">${brand()}</a><div><span class="eyebrow">MONEY, TOGETHER</span><h1>Good things<br> happen <em>together.</em></h1><p>Your money and your people.<br>Finally, on the same page.</p><div class="auth-art" aria-hidden="true"><div class="auth-mini-wallet"><div>${icon('wallet')} Weekend plans <span>Shared wallet</span></div><strong>One plan.<br>Everyone in.</strong><div class="illustration-people"><span>A</span><span>M</span><span>J</span><span>${icon('plus')}</span></div></div><div class="auth-art-note"><span>${icon('check')}</span> All settled.<small>Back to the good stuff.</small></div><div class="auth-art-spark">✳</div></div></div><small>Less keeping track. More making plans.</small></section><section class="auth-form"><div class="auth-box"><span class="eyebrow">A LITTLE MORE TOGETHER</span><h2>${register?'Make yourself at home.':'Welcome back.'}</h2><p>${register?'Your next shared plan starts here.':'Let’s pick up where you left off.'}</p><form id="auth-form" data-register="${register}">${register?`<div class="form-grid">${field('First name','first_name')}${field('Last name','last_name')}</div>`:''}${field('Phone number','phone','tel',register?'':'+96170000001')}${field('Password','password','password',register?'':'lamma-demo','minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"')}<button class="primary full" type="submit">${register?'Create account':'Sign in'}${icon('arrow')}</button><p class="form-error" role="alert"></p></form><button class="text-button" data-action="${register?'login':'register'}">${register?'Already have an account? Sign in':'New here? Create an account'}</button><div class="demo"><span class="eyebrow">EXPLORE LAMMA</span><p>Try the demo. Only test funds, always.</p><div>${button('Continue as Alex','demo','data-phone="+96170000001"','secondary')}${button('Continue as Maya','demo','data-phone="+96170000002"','secondary')}</div><small>Demo password: lamma-demo · USD</small></div></div></section></main>`;}
function navLink(k,mobile=false){const current=page==='wallet-detail'?(state.wallets.find(w=>same(w.wallet_id,walletDetail.wallet.wallet_id))?.purpose==='bill'?'bills':'wallets'):page==='bill-detail'?'bills':page;return `<button class="${mobile?'mobile-link':'nav-link'} ${current===k?'active':''}" data-page="${k}" ${current===k?'aria-current="page"':''}><span class="nav-icon">${icon(navIcons[k])}</span><span>${mobile?({overview:'Home',wallets:'Wallets',requests:'Requests',history:'Activity',more:'More'}[k]||labels[k]):labels[k]}</span>${k==='requests'&&(pendingRequests().length+state.invitations.length)?`<i>${pendingRequests().length+state.invitations.length}</i>`:''}</button>`;}
function render(){if(location.hash!==routeHash())history.replaceState(null,'',routeHash());document.title=(labels[page]||(page==='bill-detail'?'Shared bill':'Wallet'))+' · Lamma';const notifications=pendingRequests().length+state.invitations.length;app.innerHTML=`<div class="shell" data-view="${page}"><aside class="sidebar"><a class="wordmark" href="#overview">${brand()}</a><div class="workspace">YOUR WORKSPACE</div><nav aria-label="Main navigation">${Object.keys(labels).filter(k=>k!=='more').map(k=>navLink(k)).join('')}</nav><div class="sidebar-bottom"><div class="test-note">${icon('lock')}<div>Safe to explore<small>You’re using test funds.</small></div></div><button class="profile" data-page="more"><span class="avatar">${initials(state.user)}</span><span><strong>${esc(state.user.first_name)} ${esc(state.user.last_name)}</strong><small>Personal account</small></span>${icon('settings')}</button></div></aside><main class="main"><header class="topbar"><span class="desktop-crumb">Personal workspace <span>/ ${labels[page]||(page==='bill-detail'?'Shared bill':'Wallet details')}</span></span><a href="#overview" class="wordmark mobile-brand">${brand()}</a><div class="topbar-right"><span class="test-chip"><span class="dot"></span>Test mode</span><button class="notification-button" data-page="requests" aria-label="Notifications${notifications?`, ${notifications} waiting`:''}">${icon('bell')}${notifications?'<span class="notification-dot"></span>':''}</button><button class="avatar small-avatar" data-page="more" aria-label="Your account">${initials(state.user)}</button></div></header><div class="content" data-view="${page}">${content()}</div><footer><span>Lamma. Money moves together.</span><span>USD · Test funds only</span></footer></main><nav class="mobile-nav" aria-label="Mobile navigation">${['overview','wallets','history','more'].map(k=>navLink(k,true)).join('')}</nav></div>`;}
const heading=(eyebrow,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
const sectionTitle=(title,sub,link='')=>`<div class="section-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link}</div>`;
function content(){
 const p=personal();
 if(page==='wallet-detail')return walletPage();
 if(page==='bill-detail')return sharedBillPage({bill:billPreview,uid:state.user.user_id,balance:personal().balance,esc,usd,icon,button,badge,heading});
 if(page==='overview')return overviewPage();
 if(page==='wallets')return walletsPage();
 if(page==='requests')return requestsPage();
 if(page==='history')return activityPage();
 if(page==='expenses')return expensesPage();
 if(page==='bills')return billsPage();
 if(page==='business')return businessPage();
 if(page==='more')return morePage();
}
function quick(symbol,label,action){return `<button class="quick" data-action="${action}"><span>${icon(symbol)}</span>${label}</button>`;}
function walletCard(w,compact=false){
 const progress=w.target_amount?Math.min(100,Number(w.balance)/Number(w.target_amount)*100):0;
 if(compact)return `<button class="wallet-preview" data-action="wallet-view" data-wallet="${w.wallet_id}"><span class="item-icon ${w.purpose==='gift'?'peach':'sage'}">${icon(w.purpose==='gift'?'gift':'compass')}</span><span><strong>${esc(w.name)}</strong><small>${w.member_count} members · ${esc(w.purpose)}</small></span><span class="preview-value">${usd(w.balance)}${icon('arrow')}</span></button>`;
 return `<section class="panel wallet-card"><div class="wallet-card-top"><span class="item-icon ${w.purpose==='gift'?'peach':'sage'}">${icon(w.purpose==='gift'?'gift':'compass')}</span>${badge(w.status)}</div><h3>${esc(w.name)}</h3><p>${w.member_count} ${w.member_count===1?'member':'members'} · ${esc(w.member_role)}</p><div class="wallet-money">${usd(w.balance)}${w.target_amount?`<small>of ${usd(w.target_amount)}</small>`:''}</div>${w.target_amount?`<progress class="progress" max="100" value="${progress}" aria-label="Funding progress"></progress>`:''}<div class="wallet-single-action">${button('Open wallet '+icon('arrow'),'wallet-view',`data-wallet="${w.wallet_id}"`,'secondary full')}</div></section>`;
}
function tabs(items,current,attribute,label){return `<div class="filter-tabs" role="group" aria-label="${label}">${items.map(([value,name])=>`<button ${attribute}="${value}" aria-pressed="${current===value}" class="${current===value?'selected':''}">${name}</button>`).join('')}</div>`;}
function overviewPage(){
 const p=personal(),due=pendingRequests(),bills=customerBills().filter(b=>b.status!=='paid');
 return heading('PERSONAL OVERVIEW',`Hi, ${esc(state.user.first_name)}`,'All your money. More possibilities.')+`<div class="overview-grid"><section class="balance-card"><div class="balance-top"><span>${icon('wallet')} Personal wallet</span><span class="balance-currency">USD</span></div><svg class="balance-motif" viewBox="0 0 240 240" fill="none" aria-hidden="true"><path d="M40 240V90a50 50 0 0 1 100 0v150M140 90a40 40 0 0 1 80 0v150" stroke="currentColor" stroke-width="32"/></svg><div class="balance-label">Available balance</div><div class="balance">${usd(p.balance)}</div><div class="balance-bottom"><span>${icon('lock')} Test funds</span><span>•• ${String(p.wallet_id).padStart(4,'0')}</span></div></section><section class="panel quick-actions"><div><h2>Your next move</h2><p>Everyday money, a few taps away.</p></div><div class="quick-grid">${quick('send','Send money','transfer')}${quick('receive','Request money','request')}${quick('plus','Create wallet','shared')}${quick('receipt','Pay a bill','bill-lookup')}</div></section></div><div class="attention-grid"><button data-page="requests"><span>${icon('receive')} To pay</span><strong>${due.length}</strong><small>${due.length?usd(due.reduce((n,r)=>n+Number(r.amount),0))+' requested':'All caught up'}</small></button><button data-page="bills"><span>${icon('receipt')} Shared bills</span><strong>${bills.length}</strong><small>In progress</small></button><button data-page="requests" data-inbox="invitations"><span>${icon('users')} Invitations</span><strong>${state.invitations.length}</strong><small>Waiting for you</small></button></div><div class="home-sections"><section>${sectionTitle('Your group wallets','Trips, gifts, and ongoing plans.','<button class="text-button" data-page="wallets">All wallets '+icon('arrow')+'</button>')}<div class="wallet-previews">${activeShared().slice(0,3).map(w=>walletCard(w,true)).join('')||empty('Start a shared plan','Create a wallet from the shortcuts above.','wallet')}</div></section><section class="panel home-activity activity-surface"><div class="panel-heading"><h2>Latest movements</h2><button class="text-button" data-page="history">All activity ${icon('arrow')}</button></div>${transactions(state.transactions.filter(t=>same(t.sender_wallet_id,p.wallet_id)||same(t.receiver_wallet_id,p.wallet_id)).slice(0,3))}</section></div>`;
}
function walletsPage(){const wallets=sharedWallets().filter(w=>walletFilter==='all'||w.status===walletFilter);return heading('GROUP FUNDS','Shared wallets','Manage ongoing group funds and gift collections.',button(icon('plus')+'New shared wallet','shared'))+tabs([['active','Active'],['archived','Archived'],['all','All wallets']],walletFilter,'data-wallet-filter','Wallet status')+`<div class="wallet-grid">${wallets.map(w=>walletCard(w)).join('')||empty('No '+(walletFilter==='all'?'shared':walletFilter)+' wallets','Create a wallet for a trip, gift, or shared plan.','wallet')}</div><div class="page-tip">${icon('receipt')} Restaurant collections live in <button class="text-button" data-page="bills">Split a restaurant bill ${icon('arrow')}</button></div>`;}
function requestsPage(){
 const pending=r=>r.status==='pending'&&new Date(r.expires_at)>new Date();
 const rows=state.requests.filter(r=>requestFilter==='received'?same(r.payer_id,state.user.user_id)&&pending(r):requestFilter==='sent'?same(r.requester_id,state.user.user_id)&&pending(r):!pending(r));
 return heading('PAYMENT INBOX','Payment requests','Pay people, track requests you sent, or respond to invitations.',button(icon('plus')+'Request money','request'))+tabs([['received','To pay'],['sent','Sent'],['invitations','Invitations'+(state.invitations.length?' · '+state.invitations.length:'')],['history','History']],requestFilter,'data-request-filter','Request view')+(requestFilter==='invitations'?(invitations()||`<section class="panel">${empty('No invitations waiting','New wallet invitations will appear here.','users')}</section>`):`<section class="panel requests-list">${rows.map(requestCard).join('')||empty(requestFilter==='received'?'You’re all caught up':requestFilter==='sent'?'No open requests sent':'No request history yet',requestFilter==='received'?'You have no unpaid requests.':'Completed, declined, and cancelled requests stay in History.','receive')}</section>`);
}
function billRow(b,merchant=false){return `<div class="list-row bill-row"><span class="item-icon lilac">${icon('receipt')}</span><div class="row-main"><strong>${esc(b.display_name)}</strong><small>${esc(b.bill_code)} · ${date(b.created_at)}</small></div><div class="row-end"><strong>${usd(b.total_amount)}</strong>${badge(b.status)}</div>${button(merchant?'Preview bill':b.status==='paid'?'View receipt':b.shared_wallet_id?'Continue split':'Review bill',merchant?'merchant-preview':'bill-view',`data-code="${esc(b.bill_code)}"`,'secondary small')}</div>`;}
function billsPage(){const bills=customerBills().filter(b=>billFilter==='all'||(billFilter==='paid'?b.status==='paid':b.status!=='paid'));return heading('PAY AT THE TABLE','Bills & splits','Choose your items, pay your share, and track the table.',button(icon('search')+'Find & pay a bill','bill-lookup'))+tabs([['active','In progress'],['paid','Paid'],['all','All bills']],billFilter,'data-bill-filter','Bill status')+`<section class="panel customer-bills">${bills.map(b=>billRow(b)).join('')||empty(billFilter==='paid'?'No paid bills yet':'No bills in progress','Enter a bill code from the business to pay in full or start a shared bill.','receipt')}</section><div class="page-tip">${icon('business')} Issuing bills for your business? <button class="text-button" data-page="business">Open Business ${icon('arrow')}</button></div>`;}
function activityPage(){return heading('MONEY MOVEMENTS','Transactions','Completed transfers and payments. Expenses are tracked separately.')+`<div class="activity-controls"><div class="search-field">${icon('search')}<input id="activity-search" type="search" aria-label="Search transactions" placeholder="Name, type, or reference" value="${esc(activityFilter)}"></div>${select('Wallet','activity_wallet',[['personal','Personal wallet'],['all','All accessible wallets'],...sharedWallets().map(w=>[w.wallet_id,w.name])])}</div><section class="panel activity-surface" id="activity-results">${filteredTransactions()}</section><p class="page-tip">Showing up to 60 recent accessible wallet movements.</p>`;}
function expensesPage(){const expenses=state.expenses.filter(e=>expenseFilter==='all'||(expenseFilter==='open'?['unpaid','partially_settled'].includes(e.status):e.status===expenseFilter));return heading('OBLIGATIONS & REIMBURSEMENTS','Expenses','Record what you paid, then split the cost with your people.',button(icon('plus')+'Record expense','expense'))+tabs([['open','Unsettled'],['paid','Settled'],['all','All expenses']],expenseFilter,'data-expense-filter','Expense status')+`<section class="panel expense-list">${expenses.map(expenseCard).join('')||empty('No '+(expenseFilter==='open'?'unsettled':expenseFilter==='paid'?'settled':'recorded')+' expenses','Recording an expense does not transfer money. Split it to create reimbursement requests.','tag')}</section><div class="page-tip">${icon('receipt')} Splitting restaurant items? Use <button class="text-button" data-page="bills">Split a restaurant bill ${icon('arrow')}</button></div>`;}
function requestCard(r){const incoming=same(r.payer_id,state.user.user_id),expired=r.status==='pending'&&new Date(r.expires_at)<new Date(),pending=r.status==='pending'&&!expired;return `<div class="list-row request-row"><span class="item-icon ${incoming?'peach':'sage'}">${icon(incoming?'receive':'send')}</span><div class="row-main"><strong>${esc(r.description)}</strong><small>${incoming?'From '+esc(r.requester_name):'To '+esc(r.payer_name)} · ${date(r.created_at)}${r.expense_id?' · Expense split':''}</small></div><div class="row-end"><strong>${usd(r.amount)}</strong>${badge(expired?'expired':r.status)}</div>${pending?`<div class="request-actions">${incoming?button('Pay','request-pay',`data-request="${r.request_id}"`,'primary small')+button('Decline','request-decline',`data-request="${r.request_id}"`,'text-button small'):!r.expense_id?button('Cancel request','request-cancel',`data-request="${r.request_id}"`,'text-button small'):''}</div>`:''}</div>`;}
function invitations(){return state.invitations.length?`<section class="invitations"><div class="section-title"><h2>You’re invited <span class="count">${state.invitations.length}</span></h2></div>${state.invitations.map(i=>`<div class="invitation-card"><span class="item-icon sage">${icon('users')}</span><div class="row-main"><strong>${esc(i.wallet_name)}</strong><small>${esc(i.inviter_name)} invited you · Expires ${date(i.expires_at)}</small></div><div class="request-actions">${button('Accept invitation','invitation-accept',`data-invitation="${i.invitation_id}"`,'primary small')}${button('Decline invitation','invitation-decline',`data-invitation="${i.invitation_id}"`,'text-button small')}</div></div>`).join('')}</section>`:'';}
function transactions(items,walletId=personal().wallet_id){return items.length?items.map(t=>{const outgoing=same(t.sender_wallet_id,walletId),incoming=same(t.receiver_wallet_id,walletId);return `<div class="list-row"><span class="item-icon ${outgoing?'peach':incoming?'sage':'lilac'}">${icon(outgoing?'send':incoming?'receive':'activity')}</span><div class="row-main"><strong>${esc(t.transaction_type.replaceAll('_',' '))}</strong><small>${esc(t.sender_name||'Test funding')} → ${esc(t.receiver_name)} · ${date(t.created_at)}</small><small class="reference">${esc(t.reference_code)}</small></div><div class="row-end"><strong class="${incoming?'positive':''}">${outgoing?'−':incoming?'+':''}${usd(t.amount)}</strong>${badge(t.status)}</div></div>`;}).join(''):empty('A fresh start','Your money movements will appear here.','activity');}
function filteredTransactions(){const term=activityFilter.toLowerCase(),wid=activityWallet==='personal'?personal().wallet_id:activityWallet;const items=state.transactions.filter(t=>(activityWallet==='all'||same(t.sender_wallet_id,wid)||same(t.receiver_wallet_id,wid))&&`${t.transaction_type.replaceAll('_',' ')} ${t.reference_code} ${t.sender_name} ${t.receiver_name}`.toLowerCase().includes(term));return items.length?transactions(items,wid):empty('No matching activity','Try a different search or wallet.','search');}
function expenseCard(e){const shares=state.shares.filter(s=>same(s.expense_id,e.expense_id));const own=same(e.owner_user_id,state.user.user_id);return `<div class="expense-card"><div class="list-row"><span class="item-icon ${e.status==='paid'?'sage':'peach'}">${icon('tag')}</span><div class="row-main"><strong>${esc(e.title)}</strong><small>${esc(e.wallet_name||'Personal expense')} · ${date(e.expense_date)}${e.category_name?' · '+esc(e.category_name):''}</small>${e.notes?`<small>${esc(e.notes)}</small>`:''}</div><div class="row-end"><strong>${usd(e.total_amount)}</strong>${badge(e.status)}</div></div>${shares.length?`<div class="share-list">${shares.map(s=>`<div><span>${esc(s.first_name)} ${esc(s.last_name)}${same(s.user_id,state.user.user_id)?' (you)':''}</span><span>${usd(s.amount)} ${badge(s.settled?'covered':s.request_status||'pending')}</span></div>`).join('')}</div>`:''}${own&&e.status!=='cancelled'?`<div class="expense-controls">${!shares.length?button('Split expense','expense-split',`data-expense="${e.expense_id}"`,'text-button'):''}${e.status!=='paid'&&!shares.some(s=>s.request_status==='paid')?button('Cancel expense','expense-cancel',`data-expense="${e.expense_id}"`,'text-button muted-button'):''}</div>`:''}</div>`;}
function walletPage(){const detail=walletDetail,w=state.wallets.find(w=>same(w.wallet_id,detail.wallet.wallet_id));const owner=w.member_role==='owner',admin=['owner','administrator'].includes(w.member_role),active=w.status==='active';return `<button class="text-button back-button" data-page="${w.purpose==='bill'?'bills':'wallets'}">${icon('back')} ${w.purpose==='bill'?'All bills':'All wallets'}</button>`+heading(esc(w.purpose.toUpperCase())+' WALLET',esc(w.name),`${w.member_count} members · ${esc(w.member_role)} access`,active?button(icon('plus')+'Add money','contribute',`data-wallet="${w.wallet_id}"`):badge(w.status))+`<div class="wallet-detail-grid"><section class="panel detail-balance"><span class="eyebrow">POOLED TOGETHER</span><div class="balance">${usd(w.balance)}</div><p>${w.target_amount?'Working toward '+usd(w.target_amount):'USD · Shared wallet balance'}</p>${w.target_amount?`<progress class="progress" max="${Number(w.target_amount)}" value="${Number(w.balance)}" aria-label="Wallet target progress"></progress>`:''}<div class="detail-actions">${active&&owner&&w.purpose==='general'?button(icon('send')+'Send from wallet','wallet-payout',`data-wallet="${w.wallet_id}"`,'secondary'):''}${active&&admin&&w.purpose==='gift'?button(icon('gift')+'Deliver gift','gift',`data-wallet="${w.wallet_id}"`,'primary'):''}${active&&owner?button(icon('archive')+'Archive wallet','wallet-archive',`data-wallet="${w.wallet_id}"`,'text-button muted-button'):''}</div></section><section class="panel"><div class="panel-heading"><h2>Your people</h2>${active&&admin?button(icon('plus')+'Invite','member',`data-wallet="${w.wallet_id}"`,'text-button'):''}</div>${detail.members.map(m=>`<div class="member-row"><span class="avatar">${initials(m)}</span><div class="row-main"><strong>${esc(m.first_name)} ${esc(m.last_name)}${same(m.user_id,state.user.user_id)?' (you)':''}</strong><small>Joined ${date(m.joined_at)}</small></div>${badge(m.member_role)}</div>`).join('')}${detail.invitations.filter(i=>i.status==='pending'&&new Date(i.expires_at)>new Date()).map(i=>`<div class="member-row"><span class="avatar pending-avatar">${icon('receive')}</span><div class="row-main"><strong>${esc(i.phone)}</strong><small>Invitation pending</small></div>${owner?button('Cancel invitation','invitation-cancel',`data-invitation="${i.invitation_id}"`,'text-button small'):badge('pending')}</div>`).join('')}</section></div><section class="panel wallet-activity"><div class="panel-heading"><h2>Wallet activity</h2></div>${transactions(state.transactions.filter(t=>same(t.sender_wallet_id,w.wallet_id)||same(t.receiver_wallet_id,w.wallet_id)),w.wallet_id)}</section>`;}
function businessPage(){const invoices=state.bills.filter(b=>state.businesses.some(biz=>same(biz.business_id,b.business_id)));return heading('MERCHANT WORKSPACE','Business','Issue bills, manage your team, and track collections.',button(icon('plus')+'Add business','business'))+`<div class="business-grid">${state.businesses.map(b=>`<section class="panel business-card"><div class="wallet-card-top"><span class="item-icon lilac">${icon('business')}</span>${badge(b.role)}</div><h2>${esc(b.display_name)}</h2><p>Business wallet · USD</p><div class="business-balance">${usd(b.balance)}</div><div class="business-actions">${b.role!=='viewer'?button(icon('receipt')+'Issue a bill','bill',`data-business="${b.business_id}"`,'primary'):''}${b.role==='owner'?button(icon('users')+'Manage team','business-team',`data-business="${b.business_id}"`,'secondary'):''}</div></section>`).join('')||empty('Your business starts here','Create a dedicated wallet and issue your first bill.','business')}</div>${state.businesses.length?sectionTitle('Issued bills','Share the bill code with your customer.')+`<section class="panel merchant-invoices">${invoices.map(b=>billRow(b,true)).join('')||empty('No bills issued','Use Issue a bill to create your first invoice.','receipt')}</section>`:''}`;}
function morePage(){return heading('YOUR LAMMA','Your space','Your account, tools, and settings.')+`<section class="panel account-card"><span class="avatar large-avatar">${initials(state.user)}</span><div><h2>${esc(state.user.first_name)} ${esc(state.user.last_name)}</h2><p>${esc(state.user.phone)}</p><small>Personal account · USD</small></div>${button(icon('logout')+'Sign out','logout','','secondary')}</section><div class="more-grid">${['requests','expenses','bills','business'].map(k=>`<button class="panel more-tile" data-page="${k}"><span class="item-icon sage">${icon(navIcons[k])}</span><strong>${labels[k]}</strong>${icon('arrow')}</button>`).join('')}</div><section class="panel categories-panel"><div class="panel-heading"><h2>Your categories</h2>${button(icon('plus')+'New category','category','','text-button')}</div><div class="category-list">${state.categories.map(c=>`<span>${icon(c.icon)}${esc(c.name)}${c.owner_user_id?'<small>Personal</small>':''}</span>`).join('')}</div></section><div class="page-tip">${icon('lock')} You’re in test mode. No real money moves.</div>`;}
function modal(title,sub,body,submit='Continue',kind='',preset={}){dialog.innerHTML=`<div class="modal-heading"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button type="button" class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="action-form" data-kind="${kind}"><div class="modal-body">${Object.entries(preset).map(([k,v])=>`<input type="hidden" name="${k}" value="${esc(v)}">`).join('')}${body}<p class="form-error" role="alert"></p></div><div class="modal-footer">${button('Cancel','close','','secondary')}<button class="primary" type="submit">${submit}</button></div></form>`;if(!dialog.open)dialog.showModal();dialog.querySelectorAll('[data-optional]').forEach(el=>el.required=false);}
function participantRow(index,phone='',value=''){return `<div class="participant-row" data-participant><label>Participant ${index}<input name="participant_phone" type="tel" inputmode="tel" placeholder="+961…" value="${esc(phone)}" required></label><label class="share-value-label">Share<input name="participant_value" type="number" min="0.01" step="0.01" inputmode="decimal" value="${esc(value)}" placeholder="Amount or %"></label><button type="button" class="icon-button" data-action="remove-participant" aria-label="Remove participant">${icon('close')}</button></div>`;}
function splitMethod(){const method=dialog.querySelector('[name=method]').value;dialog.querySelectorAll('.share-value-label').forEach(l=>{l.hidden=method==='equal';l.querySelector('input').required=method!=='equal';});$('#split-help').textContent=method==='equal'?'Cents are distributed in participant order so the total stays exact.':method==='custom'?'Enter a USD amount for each person. Shares must match the expense total.':'Enter each person’s percentage. Shares must add up to 100%.';}
const act=(kind,body,key=crypto.randomUUID())=>api('actions/'+kind,body,key);
async function showBill(code,merchant=false){
 const requestVersion=loadVersion,nextBill=await api('bill?code='+encodeURIComponent(code));if(requestVersion!==loadVersion)return;billPreview=nextBill;billDirty=false;
 const b=billPreview;
 if(!merchant&&b.shared_wallet_id&&b.split_method==='items'){dialog.close();go('bill-detail');return;}
 const payable=!merchant&&b.status!=='paid'&&!b.shared_wallet_id;
 modal(esc(b.display_name),merchant?'Customer invoice · Share the code to collect payment.':b.status==='paid'?'Payment receipt':'Check the details before you pay.',`<div class="bill-code"><span>${esc(b.bill_code)}</span>${button('Copy code','copy-code',`data-code="${esc(b.bill_code)}"`,'text-button')}${badge(b.status)}</div>${b.items.map(i=>`<div class="bill-line"><span>${esc(i.name)}<small>${Number(i.quantity)} × ${usd(i.unit_price)}</small></span><strong>${usd(Number(i.quantity)*Number(i.unit_price))}</strong></div>`).join('')}<div class="bill-total"><span>Total</span><strong>${usd(b.total_amount)}</strong></div>${payable?select('How would you like to pay?','method',[['full','Pay the full bill'],['split','Choose what I ordered · Item split'],['custom','Pool custom contributions']]):merchant?'':b.status==='paid'?'<div class="form-tip">This bill is settled. No further payment is needed.</div>':b.member_role?button('Open collection wallet','wallet-view',`data-wallet="${b.shared_wallet_id}"`,'secondary full'):button('Join shared bill','bill-join-confirm','','secondary full')}`,payable?'Confirm':'Done',merchant?'bill-preview':'bill-confirm',{code:b.bill_code});
}
async function handleClick(e){const target=e.target.closest('button');if(!target||busy)return;try{
 if(target.dataset.page){if(target.dataset.inbox)requestFilter=target.dataset.inbox;go(target.dataset.page);return;}
 if(target.dataset.walletFilter){walletFilter=target.dataset.walletFilter;render();return;}
 if(target.dataset.billFilter){billFilter=target.dataset.billFilter;render();return;}
 if(target.dataset.expenseFilter){expenseFilter=target.dataset.expenseFilter;render();return;}
 if(target.dataset.requestFilter){requestFilter=target.dataset.requestFilter;render();return;}
 const a=target.dataset.action;if(!a)return;e.preventDefault();
 const wid=target.dataset.wallet,eid=target.dataset.expense,bid=target.dataset.business,rid=target.dataset.request,iid=target.dataset.invitation;
 if(a==='close'){dialog.close();return;}
 if(a==='register'||a==='login'){login(a==='register');return;}
 if(a==='demo'){busy=true;pendingButton(target,true,'Signing in…');await api('login',{phone:target.dataset.phone,password:'lamma-demo'});readRoute();await load();return;}
 if(a==='logout'){await api('logout',{});page='overview';walletDetail=null;history.replaceState(null,'','#overview');login();return;}
 if(a==='wallet-view'){dialog.close();const bill=state.bills.find(b=>same(b.shared_wallet_id,wid)&&b.split_method==='items');if(bill){await showBill(bill.bill_code);return;}const requestVersion=loadVersion,nextWallet=await api('wallet?id='+wid);if(requestVersion!==loadVersion)return;walletDetail=nextWallet;go('wallet-detail');return;}
 if(a==='transfer')modal('Send money','Transfer directly to a registered Lamma account.',field('Recipient phone','phone','tel')+amount()+'<div class="form-tip">Check the phone number carefully. Funds move as soon as you confirm.</div>','Send money','transfer');
 if(a==='request')modal('Request money','Send a clear request. It expires in seven days.',field('Recipient phone','phone','tel')+amount()+field('What’s it for?','description')+select('Receive into','wallet_id',walletOptions()),'Send request','request');
 if(a==='shared')modal('Create a shared wallet','Create a wallet, then invite your people.',field('Wallet name','name','text','','placeholder="e.g. Summer in Batroun"')+select('Purpose','purpose',[['general','Everyday plans & shared spending'],['gift','A gift for someone special']])+field('Target amount (optional, USD)','target_amount','number','','data-optional')+`<div id="gift-fields" hidden>${field('Gift recipient phone','gift_phone','tel','','data-optional')}<p class="form-tip">The beneficiary must be registered. They don’t need to be a member.</p></div>`,'Create wallet','shared');
 if(a==='contribute'){const bill=state.bills.find(b=>same(b.shared_wallet_id,wid)&&b.split_method==='items');if(bill){await showBill(bill.bill_code);return;}}
 if(a==='contribute')modal('Add to the plan','Transfer from your personal wallet. Fully funded bills settle automatically.',amount(),'Add money','contribute',{wallet_id:wid});
 if(a==='member')modal('Invite your people','They join only after accepting. Invitations expire in seven days.',field('Member phone','phone','tel')+'<div class="form-tip">Not registered yet? They’ll see the invitation when they create an account with this number. SMS delivery isn’t connected yet.</div>','Send invitation','member',{wallet_id:wid});
 if(a==='gift')modal('Deliver the gift','Deliver the full balance to the beneficiary’s personal wallet.','<div class="form-tip">After the transfer succeeds, this wallet is archived. Your history stays available.</div>','Deliver gift','gift',{wallet_id:wid});
 if(a==='wallet-payout')modal('Send from this wallet','As the owner, you can authorize a shared-wallet payout.',field('Recipient phone','phone','tel')+amount(),'Confirm payout','wallet-payout',{wallet_id:wid});
 if(a==='wallet-archive')modal('Archive this wallet?','Close this wallet while keeping its financial history.','<div class="form-tip">The balance must be zero and all obligations resolved. Pending invitations will be cancelled. History stays available.</div>','Archive wallet','wallet-archive',{wallet_id:wid});
 if(['invitation-accept','invitation-decline','invitation-cancel'].includes(a))modal(a==='invitation-accept'?'Join this shared wallet?':a==='invitation-decline'?'Decline this invitation?':'Cancel this invitation?',a==='invitation-accept'?'You’ll join as a participant and see this wallet’s shared activity.':'No money will move.','',a==='invitation-accept'?'Join wallet':a==='invitation-decline'?'Decline invitation':'Cancel invitation',a,{invitation_id:iid});
 if(['request-pay','request-decline','request-cancel'].includes(a)){const r=state.requests.find(r=>same(r.request_id,rid));modal(a==='request-pay'?'Settle this request?':a==='request-cancel'?'Cancel this request?':'Decline this request?',`${esc(r.description)} · ${usd(r.amount)}`,a==='request-pay'?'<div class="form-tip">Funds move from your personal wallet to the request’s destination when you confirm.</div>':'<p>No money will move.</p>',a==='request-pay'?'Pay '+usd(r.amount):a==='request-cancel'?'Cancel request':'Decline request',a,{request_id:rid});}
 if(a==='expense')modal('Record an expense','Record the total, then split and collect.',field('Title','title','text','','placeholder="e.g. Dinner with the group"')+`<div class="form-grid">${amount()}${field('Expense date','expense_date','date',new Date().toISOString().slice(0,10))}</div>`+select('Record under','wallet_id',[['','Personal expense'],...walletOptions(false)],true)+select('Category','category_id',[['','Uncategorized'],...state.categories.map(c=>[c.category_id,c.name])],true)+field('Notes (optional)','notes','text','','data-optional'),'Record expense','expense');
 if(a==='expense-split'){const ex=state.expenses.find(e=>same(e.expense_id,eid));modal('Split the expense',`${esc(ex.title)} · ${usd(ex.total_amount)}`,`<div class="form-tip">You recorded this expense as the person to reimburse. Your own share is covered; others receive requests payable to your personal wallet.</div>${select('Split method','method',[['equal','Split equally'],['custom','Custom amounts (USD)'],['percentage','By percentage']])}<div id="participants">${participantRow(1,state.user.phone)}${participantRow(2)}</div>${button(icon('plus')+'Add participant','add-participant','','text-button')}<p id="split-help" class="form-tip"></p>`,'Create split & requests','expense-split',{expense_id:eid});splitMethod();}
 if(a==='expense-cancel')modal('Cancel this expense?','Pending requests from this split will be cancelled too.','<p>Expenses with paid contributions cannot be cancelled.</p>','Cancel expense','expense-cancel',{expense_id:eid});
 if(a==='add-participant'){const list=$('#participants');if(list.children.length>=30)return;list.insertAdjacentHTML('beforeend',participantRow(list.children.length+1));splitMethod();}
 if(a==='remove-participant'&&$('#participants').children.length>1)target.closest('[data-participant]').remove();
 if(a==='category')modal('Your own category','Create a private category for your expenses.',field('Category name','name'),'Create category','category');
 if(a==='business')modal('Create a business','Business funds stay separate from your personal wallet.',field('Business name','name'),'Create business','business');
 if(a==='business-team'){const team=state.teams.filter(t=>same(t.business_id,bid));modal('Your business team','Only the primary owner can grant or revoke access.',`<div class="team-list">${team.map(t=>`<div class="member-row"><span class="avatar">${initials(t)}</span><div class="row-main"><strong>${esc(t.first_name)} ${esc(t.last_name)}</strong><small>${esc(t.phone)}</small></div>${badge(t.role)}${t.role!=='owner'?button('Revoke','business-revoke',`data-business="${bid}" data-phone="${esc(t.phone)}"`,'text-button small'):''}</div>`).join('')}</div><h3 class="form-section-title">Add or update access</h3>${field('Team member phone','phone','tel')}${select('Role','role',[['viewer','Viewer · Read-only bills & balance'],['cashier','Cashier · View and issue bills'],['manager','Manager · View and issue bills']])}`,'Save access','business-access',{business_id:bid});}
 if(a==='business-revoke')modal('Revoke team access?','This person will immediately lose business access.','<p>Your primary owner permissions are preserved.</p>','Revoke access','business-revoke',{business_id:bid,phone:target.dataset.phone});
 if(a==='bill')modal('Issue a bill','Add the items your customer will review.',`<div id="bill-items">${billItemRow()}</div>${button(icon('plus')+'Add item','add-bill-item','','text-button')}`,'Create bill','bill',{business_id:bid});
 if(a==='add-bill-item')$('#bill-items').insertAdjacentHTML('beforeend',billItemRow());
 if(a==='remove-bill-item'&&$('#bill-items').children.length>1)target.closest('[data-bill-item]').remove();
 if(a==='bill-lookup')modal('Find a bill','Enter the code shared by the business.',field('Bill code','code','text','','placeholder="B-1234ABCD"'),'Review bill','bill-lookup');
 if(a==='bill-view')await showBill(target.dataset.code);
 if(a==='merchant-preview')await showBill(target.dataset.code,true);
 if(a==='retry')await load();
 if(a==='bill-save')$('#bill-claim-form').requestSubmit();
 if(a==='copy-code'||a==='share-bill'){const code=target.dataset.code||billPreview.bill_code;const link=location.origin+location.pathname+'#bill/'+encodeURIComponent(code);try{if(a==='share-bill'&&navigator.share)await navigator.share({title:'Lamma shared bill',text:'Join our table and choose your items.',url:link});else{if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(a==='copy-code'?code:link);toast(a==='copy-code'?'Bill code copied.':'Bill link copied.');}}catch(error){if(error.name!=='AbortError'){modal('Share this bill','Copy the code or link below.',field('Bill reference','reference','text',a==='copy-code'?code:link,'readonly'),'Done','ui-done');dialog.querySelector('[name=reference]').select();}}}
 if(a==='bill-refresh'){if(billDirty&&!window.confirm('Refresh and discard your unsaved item selections?'))return;billDirty=false;await load();}
 if(a==='bill-join-confirm')modal('Join this shared bill?','Choose your items and pay into the temporary bill wallet.','<div class="form-tip">You’ll join as a participant and see shared activity. Join only the bill you intend to pay.</div>','Join shared bill','bill-join',{code:billPreview.bill_code});
 if(a==='bill-share-confirm'){
  if(billDirty)throw new Error('Save your changed items before paying.');
  modal('Pay your selected items?',`${esc(billPreview.display_name)} · ${usd(billPreview.my_total)}`,`${billPreview.selections.map(i=>`<div class="bill-line"><span>${Number(i.quantity)} × ${esc(i.name)}</span><strong>${usd(i.allocated_amount)}</strong></div>`).join('')}<div class="bill-total"><span>Your total</span><strong>${usd(billPreview.my_total)}</strong></div><div class="form-tip">Your personal wallet pays the temporary shared bill wallet. The business is paid once the full bill is collected.</div>`,'Pay '+usd(billPreview.my_total),'bill-pay-share',{code:billPreview.bill_code,quote:billPreview.quote});
 }

 }catch(e){toast(e.message,true);}finally{if(target.dataset.action==='demo'){busy=false;pendingButton(target,false);}}}
function billItemRow(){return `<div class="bill-item-input" data-bill-item>${field('Item name','item_name','text','','placeholder="e.g. Mezze platter"')}<div class="form-grid">${field('Quantity','item_quantity','number','1','step="1"')}${field('Unit price (USD)','item_price','number')}</div><button type="button" class="text-button muted-button" data-action="remove-bill-item">Remove item</button></div>`;}
app.addEventListener('click',handleClick);dialog.addEventListener('click',handleClick);
app.addEventListener('input',e=>{if(e.target.id==='activity-search'){activityFilter=e.target.value;$('#activity-results').innerHTML=filteredTransactions();}});
app.addEventListener('change',e=>{if(e.target.name==='activity_wallet'){activityWallet=e.target.value;$('#activity-results').innerHTML=filteredTransactions();}});
dialog.addEventListener('change',e=>{if(e.target.name==='method'&&$('#participants'))splitMethod();if(e.target.name==='purpose'){$('#gift-fields').hidden=e.target.value!=='gift';dialog.querySelector('[name=gift_phone]').required=e.target.value==='gift';}});
app.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();if(busy)return;busy=true;const form=e.target,b=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');pendingButton(submit,true,form.dataset.register==='true'?'Creating account…':'Signing in…');lockForm(form,true);try{await api(form.dataset.register==='true'?'register':'login',b);readRoute();await load();}catch(err){formError(form,err);}finally{busy=false;lockForm(form,false);pendingButton(submit,false);}});
dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
dialog.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.target,b=Object.fromEntries(new FormData(form)),kind=form.dataset.kind,submit=form.querySelector('[type=submit]');busy=true;pendingButton(submit,true,'Working…');lockForm(form,true);form.querySelector('[role=alert]').textContent='';try{
 if(kind==='ui-done'||kind==='bill-preview'){dialog.close();return;}
 if(kind==='bill-lookup'){await showBill(b.code);return;}
 let operation=kind;
 if(kind==='bill-confirm'){if(billPreview.status==='paid'||billPreview.shared_wallet_id){dialog.close();return;}operation=b.method==='full'?'bill-pay':'bill-split';if(operation==='bill-split')b.method=b.method==='split'?'items':'custom';else delete b.method;}
 if(kind==='expense-split'){b.participants=[...form.querySelectorAll('[data-participant]')].map(row=>({phone:row.querySelector('[name=participant_phone]').value,value:row.querySelector('[name=participant_value]').value}));delete b.participant_phone;delete b.participant_value;}
 if(kind==='bill'){b.items=[...form.querySelectorAll('[data-bill-item]')].map(row=>({name:row.querySelector('[name=item_name]').value,quantity:row.querySelector('[name=item_quantity]').value,price:row.querySelector('[name=item_price]').value}));delete b.item_name;delete b.item_quantity;delete b.item_price;}
 const payload=JSON.stringify({operation,b});if(form.dataset.payload!==payload){form.dataset.key=crypto.randomUUID();form.dataset.payload=payload;}const result=await act(operation,b,form.dataset.key);
 if(kind==='bill-confirm'&&operation==='bill-split'){if(b.method==='items'){billPreview=await api('bill?code='+encodeURIComponent(b.code));page='bill-detail';billDirty=false;}else{walletDetail=await api('wallet?id='+result.wallet_id);page='wallet-detail';}}
 if(kind==='bill-join'||kind==='bill-pay-share'){if(billPreview.split_method==='custom'){walletDetail=await api('wallet?id='+result.wallet_id);page='wallet-detail';}else page='bill-detail';billDirty=false;}
 if(kind==='shared'){page='wallets';walletFilter='active';}
 if(kind==='request'){page='requests';requestFilter='sent';}
 if(kind==='expense'){page='expenses';expenseFilter='open';}
 if(kind==='expense-split'){page='expenses';expenseFilter=result.status==='paid'?'paid':'open';}
 if(kind==='bill')page='business';
 dialog.close();const refreshed=await load();if(refreshed&&kind==='invitation-accept'){const linked=state.bills.find(bill=>same(bill.shared_wallet_id,result.wallet_id));if(linked?.split_method==='items')await showBill(linked.bill_code);else{walletDetail=await api('wallet?id='+result.wallet_id);go('wallet-detail');}}if(refreshed)toast({'bill-pay-share':'Your share is paid into the bill wallet.','bill-join':'You joined the bill. Choose what you ordered.',member:'Invitation sent. They’ll join after accepting.','expense-split':'Split created. Payment requests are on their way.','invitation-accept':'You’re in. Time to make plans.','wallet-archive':'Wallet archived. Your history stays with you.'}[kind]||'Done. Your changes are saved.');else toast('Saved, but the view could not refresh. Please try refreshing.',true);if(kind==='bill'&&refreshed)await showBill(result.bill_code,true);
 }catch(err){formError(form,err);}finally{busy=false;lockForm(form,false);pendingButton(submit,false);}});
window.addEventListener('focus',()=>{if(state&&!busy&&!dialog.open&&!billDirty)load();});
function syncBillCheckout(){
 const form=$('#bill-claim-form');if(!form)return;
 const selections=[...form.querySelectorAll('[data-order-item]')].filter(row=>row.querySelector('[type=checkbox]').checked).map(row=>({id:row.dataset.orderItem,quantity:Number(row.querySelector('[type=number]').value)}));
 const saved=billPreview.selections.map(s=>({id:String(s.item_id),quantity:Number(s.quantity)}));
 billDirty=JSON.stringify(selections)!==JSON.stringify(saved);
 const action=$('#bill-checkout-action'),label=$('#checkout-label'),total=$('#checkout-amount'),status=$('#bill-selection-state');
 const saveMode=billDirty||!billPreview.quote;action.dataset.action=saveMode?'bill-save':'bill-share-confirm';action.disabled=busy||(!billDirty&&!billPreview.quote);action.innerHTML=(saveMode?'Save my items':'Pay my share')+' '+icon(saveMode?'check':'send');
 label.textContent=billDirty?'Estimated share':'Saved share';
 const estimate=selections.reduce((n,s)=>n+Math.round(Number(billPreview.items.find(i=>same(i.item_id,s.id)).unit_price)*s.quantity*100),0)/100;
 total.textContent=usd(billDirty?estimate:billPreview.my_total);
 status.textContent=billDirty?'Unsaved changes. Save to review your exact share.':billPreview.quote?'Items saved. Ready to pay.':'Check your items to get started.';
}
app.addEventListener('input',e=>{if(e.target.closest('#bill-claim-form'))syncBillCheckout();});
app.addEventListener('change',e=>{
 const form=e.target.closest('#bill-claim-form');if(!form)return;
 const row=e.target.closest('[data-order-item]');if(row){const checkbox=row.querySelector('[type=checkbox]');row.querySelector('[type=number]').disabled=!checkbox.checked;row.classList.toggle('is-selected',checkbox.checked);}
 syncBillCheckout();
});
app.addEventListener('submit',async e=>{
 if(e.target.id!=='bill-claim-form')return;e.preventDefault();if(busy)return;
 const form=e.target,submit=$('#bill-checkout-action');busy=true;pendingButton(submit,true,'Saving items…');lockForm(form,true);form.querySelector('[role=alert]').textContent='';
 try{
  const items=[...form.querySelectorAll('[data-order-item]')].filter(row=>row.querySelector('[type=checkbox]').checked).map(row=>({item_id:row.dataset.orderItem,quantity:row.querySelector('[type=number]').value}));
  const body={code:billPreview.bill_code,revision:billPreview.split_revision,items};const payload=JSON.stringify(body);if(form.dataset.payload!==payload){form.dataset.key=crypto.randomUUID();form.dataset.payload=payload;}
  await act('bill-claim',body,form.dataset.key);billDirty=false;const refreshed=await load();toast(refreshed?(items.length?'Your items are saved. Review your share, then pay.':'Your unpaid selections have been released.'):'Saved, but the view could not refresh. Please try refreshing.',!refreshed);
 }catch(err){formError(form,err);}finally{busy=false;lockForm(form,false);pendingButton(submit,false);}
});
